/* From Uiverse.io by MRez321  - Tags: button, switch, checkbox, theme-switch, toggle switch */
.__UIV_SCOPE__ .theme-switch {
  position: relative;
  display: flex;
  justify-content: center;
  direction: rtl;
}

.__UIV_SCOPE__ #theme-checkbox {
  display: none;
}

.__UIV_SCOPE__ #theme-checkbox + label {
  /* change the font-size below to change the size of the switch button*/
  font-size: 2rem;
  height: 1em;
  width: 2.5em;
  border-radius: 0.25em;
  cursor: pointer;
  display: flex;
  justify-content: space-between;
  background-color: #cecece;
  position: relative;
}

.__UIV_SCOPE__ #theme-checkbox:checked + label {
  background-color: #3a3a3a;
}

.__UIV_SCOPE__ #theme-checkbox + label:active {
  transform: scale(0.85);
  transition: transform 0.2s;
}

.__UIV_SCOPE__ #theme-checkbox + label div {
  width: 0.8em;
  height: 0.8em;
  border-radius: inherit;
  position: absolute;
  top: 0.1em;
  left: 0.1em;
  z-index: 10;
  transition: 0.5s cubic-bezier(1, 0.33, 0.11, 1.34);
  background-color: #f2f2f2;
}

.__UIV_SCOPE__ #theme-checkbox:checked + label div {
  /* left: calc(2.5em - .8em - .1em); */
  left: 1.6em;
  background-color: #212121;
}

.__UIV_SCOPE__ #theme-checkbox + label span {
  display: flex;
}

.__UIV_SCOPE__ #theme-checkbox + label svg {
  display: inline-block;
  height: 1em;
  width: 1em;
  padding: 0.15em;
  box-sizing: border-box;
}

.__UIV_SCOPE__ #theme-checkbox + label span:first-of-type {
  color: #3a3a3a;
}

.__UIV_SCOPE__ #theme-checkbox + label span:last-of-type {
  color: #cecece;
}
